const presetMenu=byId('noiseNPreset'),presetControls=card.querySelectorAll('#noiseNPreset,[data-noise-preset-step]');let presetBusy=false;
async function applyNoisePreset(id){
 const preset=root.MygrainNoisePresets.get(id);if(!preset||presetBusy){sync();return;}
 try{
  if(root.mygrainCardHistory?.busy||root.mygrainSongBeta?.busy||root.mygrainSongBeta?.playing||stateSaveSuspended)throw Error('Finish the current edit or stop Song playback before choosing an N filter preset.');
  presetBusy=true;for(const control of presetControls)control.disabled=true;
  const action=()=>{restore({...preset,enabled:settings().enabled});syncPerformanceControlState();saveState()};
  if(root.mygrainCardHistory)await root.mygrainCardHistory.runDraftEdit('N filter preset',action);else action();
 }catch(error){setStatus(error.message,'error')}
 finally{if(presetBusy){presetBusy=false;for(const control of presetControls)control.disabled=false;}sync();}
}
presetMenu.addEventListener('change',()=>applyNoisePreset(presetMenu.value));
for(const button of card.querySelectorAll('[data-noise-preset-step]'))button.addEventListener('click',()=>{
 if(presetBusy)return;
 // Step in the grouped menu's visible order, skip Custom and wrap at either end.
 const options=[...presetMenu.options].filter(option=>option.value&&!option.disabled),step=Number(button.dataset.noisePresetStep),index=options.findIndex(option=>option.value===presetMenu.value);
 if(!options.length)return;
 const next=index<0?(step>0?0:options.length-1):(index+step+options.length)%options.length;
 return applyNoisePreset(options[next].value);
});
